### Load 3D Models with GLTFLoader in Three.js

Source: https://context7.com/mrdoob/three.js/llms.txt

This example demonstrates how to load GLTF 3D models using Three.js's GLTFLoader. It includes setting up an optional DRACOLoader for compressed models, adding the loaded model to the scene, accessing and playing animations with AnimationMixer, and traversing the model's objects to modify properties like shadow casting.

```javascript
import * as THREE from 'three';
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';
import { DRACOLoader } from 'three/addons/loaders/DRACOLoader.js';

const loader = new GLTFLoader();

// Optional: Set up Draco decoder for compressed models
const dracoLoader = new DRACOLoader();
dracoLoader.setDecoderPath( 'https://www.gstatic.com/draco/versioned/decoders/1.5.6/' );
loader.setDRACOLoader( dracoLoader );

// Load a GLTF model
loader.load(
  'models/scene.glb',
  ( gltf ) => {
    // Add the entire scene
    scene.add( gltf.scene );

    // Access animations
    if ( gltf.animations.length > 0 ) {
      const mixer = new THREE.AnimationMixer( gltf.scene );
      const action = mixer.clipAction( gltf.animations[ 0 ] );
      action.play();

      // Update mixer in animation loop
      function animate() {
        mixer.update( clock.getDelta() );
        renderer.render( scene, camera );
      }
    }

    // Traverse and modify objects
    gltf.scene.traverse( ( child ) => {
      if ( child.isMesh ) {
        child.castShadow = true;
        child.receiveShadow = true;
      }
    } );
  },
  ( progress ) => {
    console.log( ( progress.loaded / progress.total * 100 ) + '% loaded' );
  },
  ( error ) => {
    console.error( 'Error loading model:', error );
  }
);
```

